import React, { useState, useEffect } from 'react';
import { Save, X, Plus } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const ProfilePage = () => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [profileData, setProfileData] = useState({
    fullName: '',
    bio: '',
    github: '',
    portfolio: ''
  });

  const [skills, setSkills] = useState(['React', 'Node.js']);
  const [newSkill, setNewSkill] = useState('');

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        navigate('/');
        return;
      }

      try {
        // السطر 20: التصحيح الحاسم هنا باستخدام الـ backticks () بدلاً من (' ')
        const response = await axios.get('http://127.0.0.1:8000/api/profile/', {
          headers: { 
            'Authorization':` Bearer ${token}` 
          }
        });

        if (response.data) {
          setProfileData({
            fullName: response.data.user?.username || '',
            bio: response.data.bio || '',
            github: response.data.github || '',
            portfolio: response.data.portfolio || ''
          });
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchProfile();
  }, [navigate]);

  if (isLoading) return <div style={{ textAlign: 'center', marginTop: '50px' }}>Loading...</div>;

  return (
    <div style={{ padding: '40px', backgroundColor: '#fdfbff', minHeight: '100vh' }}>
      <div style={{ maxWidth: '800px', margin: '0 auto', backgroundColor: 'white', borderRadius: '15px', padding: '30px', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}>
        <h2 style={{ color: '#4a3f6b', marginBottom: '20px' }}>Digital CV Settings</h2>
        
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
          <div>
            <label style={{ fontWeight: 'bold' }}>Full Name</label>
            <input 
              style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ddd', marginTop: '5px' }}
              value={profileData.fullName}
              onChange={(e) => setProfileData({ ...profileData, fullName: e.target.value })}
            />
          </div>
          <div>
            <label style={{ fontWeight: 'bold' }}>GitHub URL</label>
            <input 
              style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ddd', marginTop: '5px' }}
              value={profileData.github}
              onChange={(e) => setProfileData({ ...profileData, github: e.target.value })}
            />
          </div>
        </div>

        <button style={{ backgroundColor: '#4a3f6b', color: 'white', padding: '12px 25px', borderRadius: '10px', border: 'none', display: 'block', margin: '30px auto', cursor: 'pointer' }}>
          <Save size={18} style={{ marginRight: '8px' }} /> Save Digital CV
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
